-- ════════════════════════════════════════════════════════════════════════
-- 1063-tower-formula-chest-catalogue.generated.sql — THE HEARTH CHEST: ITS OPEN KEY TABLE, WHAT EACH KEY ALWAYS HOLDS, ITS WEAPON CHANCE, THE HEARTH'S WARMTH AND THE STOKES.
-- Generated by tools/gen-chests.mjs from src/data/chests.js (the salts each key holds derived from src/data/temper.js TEMPER_MATERIALS; the
--   weapon families from src/data/gear-tiers.js and every weapon item's own fields). Any hand edit FAILS `node tools/gen-chests.mjs --check`.
-- STATUS: STAGED, NOT APPLIED (lane/tower-boss-formula, systems-engineer, 2026-11-22: the Burning Tower rebuilt from formulas). A FORWARD FILE:
--   2027-05-12-catacomb-gold-platinum-chest-catalogue (applied with v0.2.141) whole, with each key's first landing and weapon chance GENERATED
--   (src/data/chests.js landingForLevel: the landing whose floor Level reaches its weapons' item Level; KEY_ODDS: the chance halves a metal).
--   No other row moves. The Coordinator applies (tools/apply-migration.mjs, one file, never inside begin/commit). ORDER: after
--   1063-tower-formula-tower-catalogue.generated.sql, before the edge deploy of the same lane. No function body: the live hr_chest_open and the
--   key mint read the table as it stands.
-- hr_chests (one row today); hr_chest_key_families (2: a key family's caps, every key of the family sharing them: the keys one hero may
--   open a UTC week and the held limit past which a new key of it does not drop); hr_chest_keys (12 rows: each in a family; the open
--   table, a Tower landing's key is the highest Tower row at or under it); hr_chest_stokes (3: a stoke count's multiplier and its price
--   in keys' worth of Cinders); hr_chest_luck (one row: the warmth step and cap, the own-family weight, the per-call clamp);
--   hr_chest_families (the 7 weapon families, the "types"); hr_chest_weapons (each key's
--   weapon a family: 28 rows; a key short of its 7 is refused chest_not_ready); hr_chest_weapon_families (120
--   weapon items and their family); hr_chest_outfits (12: the super-rare outfits, each outfit's bundle item and its chance on every
--   key in permille, src/data/chests.js CHEST_OUTFITS; lane/c-sweeps-coat-drop, the Sweep's Coat). All rewritten whole: no player row
--   points at any of them (the key, Cinders and bundle items are hr_items rows).
-- hr_chest_armor (48: each Catacomb key's piece a slot and weight, the server's heavy / medium / light; a key short of its 6 is
--   refused chest_not_ready, a later key tier or wing until its pieces ship).
-- RLS on, no policy, no client grant: only SECURITY DEFINER functions read them. ON THE EA SECURITY LIST with the Tower and the descent.
-- REVERSIBLE: after 2027-05-08-catacombs.sql's reversal, delete the catacomb rows, drop hr_chest_armor and the three new key columns (put the
--   (key_family, from_landing) key back); the nine tables after 2027-04-27-tower-chest.sql's.
-- ════════════════════════════════════════════════════════════════════════
create table if not exists public.hr_chests (
  chest_id text primary key check (chest_id ~ '^[a-z0-9_]{1,40}$'),
  name     text not null
);
create table if not exists public.hr_chest_key_families (
  key_family     text primary key check (key_family ~ '^[a-z0-9_]{1,40}$'),
  name           text not null,
  opens_per_week int  not null check (opens_per_week between 1 and 1000),
  held_max       int  not null,
  constraint hr_chest_key_families_held check (held_max >= opens_per_week)
);
create table if not exists public.hr_chest_keys (
  key_id       text primary key check (key_id ~ '^[a-z0-9_]{1,40}$'),
  key_family   text not null,
  item_id      text not null unique,
  name         text not null,
  from_landing int  not null check (from_landing > 0),
  weapon_pm    int  not null check (weapon_pm between 1 and 1000),
  weapon_tier  int  not null check (weapon_tier between 1 and 10),
  skill_plus   int  not null check (skill_plus >= 1),
  cinders      int  not null check (cinders > 0),
  salts_item   text not null,
  salts_qty    int  not null check (salts_qty > 0),
  food_item    text not null,
  food_qty     int  not null check (food_qty > 0),
  constraint hr_chest_keys_from unique (key_family, from_landing)
);
-- THE CATACOMB KEYS (lane/c-catacombs): a key names the run ground whose doors mint it, what a hit pays and an armor key's slot lean. Two wings'
-- keys of one metal share a door, so the open table is unique by ground, not by family; an armor key carries no +skill.
-- a key family's switch (lane/c-catacombs): the feature that hides its door, its keys at the chest and its section (burning_tower, unmarked_catacombs)
alter table public.hr_chest_key_families add column if not exists switch_id text check (switch_id ~ '^[a-z0-9_]{1,40}$');
alter table public.hr_chest_keys add column if not exists ground text;
alter table public.hr_chest_keys add column if not exists gear text;
alter table public.hr_chest_keys add column if not exists helmet_pm int;
alter table public.hr_chest_keys drop constraint if exists hr_chest_keys_from;
alter table public.hr_chest_keys drop constraint if exists hr_chest_keys_skill_plus_check;
create table if not exists public.hr_chest_armor (
  key_id  text not null,
  slot    text not null check (slot in ('helmet', 'boots')),
  weight  text not null check (weight in ('heavy', 'medium', 'light')),
  item_id text not null,
  primary key (key_id, slot, weight)
);
create table if not exists public.hr_chest_stokes (
  stokes int primary key check (stokes between 1 and 9),
  pm     int not null check (pm > 1000),
  keys   int not null check (keys > 0)
);
create table if not exists public.hr_chest_luck (
  id             boolean primary key default true check (id),
  warmth_step_pm int not null check (warmth_step_pm >= 0),
  warmth_cap_pm  int not null check (warmth_cap_pm >= 1000),
  own_pm         int not null check (own_pm between 0 and 1000),
  per_call       int not null check (per_call between 1 and 100)
);
create table if not exists public.hr_chest_families (
  family text primary key check (family ~ '^[a-z0-9_]{1,40}$'),
  ord    int  not null unique
);
create table if not exists public.hr_chest_weapons (
  key_id  text not null,
  family  text not null,
  item_id text not null unique,
  primary key (key_id, family)
);
create table if not exists public.hr_chest_weapon_families (
  item_id text primary key,
  family  text not null
);
create table if not exists public.hr_chest_outfits (
  key_id    text not null,
  outfit_id text not null check (outfit_id ~ '^[a-z0-9_]{1,40}$'),
  item_id   text not null check (item_id ~ '^[a-z0-9_]{1,40}$'),
  pm        int  not null check (pm between 1 and 1000),
  primary key (key_id, outfit_id)
);
do $$
declare t text;
begin
  foreach t in array array['hr_chests', 'hr_chest_key_families', 'hr_chest_keys', 'hr_chest_stokes', 'hr_chest_luck', 'hr_chest_families', 'hr_chest_weapons', 'hr_chest_weapon_families', 'hr_chest_outfits', 'hr_chest_armor'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from public, anon, authenticated, service_role', t);
  end loop;
end $$;
comment on table public.hr_chest_key_families is '1063-tower-formula-chest-catalogue.generated.sql: the key families (src/data/chests.js KEY_FAMILIES, Tyler 2026-11-16): every key of a family shares its caps, opens_per_week keys one hero may use a UTC week (hr_chest_open, from chest_opens) and held_max, the held limit past which a new key of the family does not drop (hr_tower_key_mint). Read by hr_tower_key_mint, hr_chest_open and hr_chest_section.';
comment on table public.hr_chest_keys is '1063-tower-formula-chest-catalogue.generated.sql: the Hearth Chest''s open key table (src/data/chests.js CHEST_KEYS): each key in a family (hr_chest_key_families); a Tower landing''s key is the highest Tower row at or under it; what each key always holds; its base weapon chance (permille). Read by hr_tower_key_mint, hr_chest_open and hr_chest_section.';
comment on table public.hr_chest_luck is '1063-tower-formula-chest-catalogue.generated.sql: the Hearth''s warmth (a dry key warms the next by warmth_step_pm of its base, up to warmth_cap_pm), the own-family weight and the per-call clamp (src/data/chests.js CHEST_LUCK). One row.';
comment on table public.hr_chest_weapons is '1063-tower-formula-chest-catalogue.generated.sql: each key''s tower weapon a family (src/data/chests.js weapons). A key without one for every hr_chest_families row is not ready: hr_chest_open refuses it.';
comment on table public.hr_chest_armor is '1063-tower-formula-chest-catalogue.generated.sql: each Catacomb key''s armor piece a slot and weight (src/data/chests.js CATACOMB_KEYS armor, from src/data/catacomb-armor.js). A key without all six is not ready: hr_chest_open refuses it. The slot is the key''s lean (hr_chest_keys.helmet_pm), the weight the opener''s own in that slot own_pm of the time.';
comment on table public.hr_chest_outfits is '1063-tower-formula-chest-catalogue.generated.sql: the super-rare outfits (src/data/chests.js CHEST_OUTFITS): each outfit''s bundle item and its chance on every key, permille. hr_chest_open rolls one outfit a key on its own stream, the rows stacked in outfit order (at most one a key, each at its chance). Read by hr_chest_open and hr_chest_section.';

delete from public.hr_chests;
delete from public.hr_chest_weapons;
delete from public.hr_chest_armor;
delete from public.hr_chest_keys;
